using System;using System.IO;using System.Reflection;using System.Threading;using System.Web.Script.Serialization;
class MonitorAvailabilityTests {
 static int checks,failures;static void Check(bool ok,string n){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+n);}
 static SystemSample Cached(int interval,int age){using(var t=new Telemetry()){var setting=typeof(Telemetry).GetField("RefreshMilliseconds");if(setting!=null)setting.SetValue(t,interval);typeof(Telemetry).GetField("extended",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(t,new SystemSample{Utc=DateTime.UtcNow.AddSeconds(-age),DiskBusy=23.5,CpuMHz=3500,DiskState="fixture"});return t.Sample(1,1,2);}}
 [STAThread]static int Main(string[] args){try{
 Check(Cached(5000,6).DiskBusy==23.5,"five-second polling preserves still-valid six-second disk sample");
 Check(!Cached(1000,6).DiskBusy.HasValue,"one-second polling still hides expired disk sample");
 Check(!Cached(5000,16).DiskBusy.HasValue,"five-second polling cannot display indefinitely stale disk sample");
 Check(!Cached(5000,-10).DiskBusy.HasValue,"future-dated disk sample is not fresh");
 string csv=Path.Combine(args[0],"sensor-fixture.csv");string header=",/intelcpu/0/temperature/0,/intelcpu/0/temperature/1,/nvidiagpu/0/temperature/0,/intelcpu/0/load/0\nTime,CPU,Core,GPU,Load\n";string stamp=DateTime.Now.AddSeconds(-2).ToString("G",System.Globalization.CultureInfo.InvariantCulture);File.WriteAllText(csv,header+stamp+",61.5,72.25,55,99\n");var values=HardwareLog.ReadFile(csv,DateTime.UtcNow);Check(values.Cpu==72.25&&values.Gpu==55,"CPU log uses core/package maximum and separates GPU and load");File.AppendAllText(csv,stamp+",99");Check(HardwareLog.ReadFile(csv,DateTime.UtcNow).Cpu==72.25,"partial CSV append does not corrupt last complete sample");File.WriteAllText(csv,header+DateTime.Now.AddMinutes(-2).ToString("G",System.Globalization.CultureInfo.InvariantCulture)+",61,70,55,99\n");Check(HardwareLog.ReadFile(csv,DateTime.UtcNow)==null,"expired sensor logs cannot masquerade as current temperature");File.WriteAllText(csv,header+stamp+",NaN,999,Infinity,99\n");Check(!HardwareLog.ReadFile(csv,DateTime.UtcNow).Cpu.HasValue,"invalid sensor numbers are rejected");
 string dir=Path.Combine(args[0],"no-trust-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var r=new CodexQuotaReader(dir);var cfg=new CodexQuotaConfig();r.Sample(cfg);Thread.Sleep(300);var quota=r.Sample(cfg);var s=new SystemSample{Quota=quota};Check(TaskbarPainter.Format(s,"codex5h",new TaskbarAppearance())=="待授权","unapproved quota has actionable taskbar status");Check(!quota.Remaining(300,DateTime.UtcNow).HasValue,"unapproved quota never supplies old numeric allowance");
 Check(new SystemSample().TemperatureState.Contains("LibreHardwareMonitor"),"CPU sensor absence identifies required provider");
 using(var bar=new TaskbarMonitor()){bool found=false;foreach(System.Windows.Forms.ToolStripItem i in bar.ContextMenuStrip.Items)if(i.Text=="Codex额度与授权")found=true;Check(found,"taskbar offers direct quota authorization entry");}
 }catch(Exception e){failures++;Console.WriteLine(e);}File.WriteAllText(Path.Combine(args[0],"availability-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures}));return failures==0?0:1;}
}
